// features/lifecycle.feature: Once a vendor is sent back, its other documents cannot be decided
import { expect, expectStatus, test } from "../../fixtures";

test("approving another document after a rejection is refused with vendor_not_in_review", { tag: "@LIF-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { extractions } = await factory.vendorInReview();
  const rejected = await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "W-9 is missing the signature." },
    }),
    200,
  );
  expect(rejected.status).toBe("rejected");

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_not_in_review");
});
